"""Compare row-preserving and through-R regroupings in the tetrahedral Hall frame. The square seed's mutual opposite-port assignment supplies a row pairing; it is not an edge color in a Hall output."""
from itertools import combinations
rows=['BRNN','BNRN']; X=list(combinations(range(4),2)); P=list(combinations(range(6),2)); T=[t for t in combinations(P,3) if len(set(sum(t,())))==6];B=rows[0].index('B');assert B==rows[1].index('B');U,V=[s.index('R') for s in rows];Q,=set(range(4))-{B,U,V};E=lambda a,b:X.index(tuple(sorted((a,b))));pair=lambda *xs:tuple(sorted(xs));f=(1,0,3,2);g=(0,2,1,3);h=tuple(g[f[g[i]]] for i in range(4));op=lambda f:pair(*(E(i,j) for i,j in enumerate(f) if i<j)); d0,d1=op(f),op(h);assert (d0,d1)==tuple(pair(E(B,s.index('R')),E(*[i for i,x in enumerate(s) if x=='N'])) for s in rows);other=pair(*(set(range(6))-set(d0+d1)));row_end=pair(d0,d1,other);via=pair(pair(E(B,U),E(U,Q)),pair(E(B,V),E(V,Q)),other);fan=P.index(pair(E(B,f[B]),E(B,h[B])));assert (fan,15+T.index(row_end),15+T.index(via))==(0,29,26);print('B fan',fan,'partition preserving each row',15+T.index(row_end),'partition preserving incidence at R',15+T.index(via));assert all(not(set(X[i])&set(X[j])) for i,j in row_end);assert sum(bool(set(X[i])&set(X[j])) for i,j in via)==2
